using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using ZX.Platform.Identity.Api.AI.Queries;
using ZX.Platform.Identity.Api.Contracts;
using ZX.Platform.Identity.Api.Localization;
using ZX.Platform.Identity.Application.Authorization;
using ZX.Platform.Identity.Application.Inventory.Stocktake;
using ZX.Platform.Identity.Application.Inventory.Stocktake.Dtos;

namespace ZX.Platform.Identity.Api.Controllers;

[ApiController]
[Route("api/[controller]")]
[Authorize(Policy = IdentityPermissions.InventoryStocktakeRead)]
public sealed class InventoryStocktakeController(IStocktakeReportService reports, IApiMessageLocalizer messages) : ControllerBase
{
    // 全局报表，不标注 RequireSbu；功能权限仍由后端独立校验。
    [AiQuery]
    [HttpGet("list")]
    [ProducesResponseType(typeof(ApiResponse<StocktakeListDto>), StatusCodes.Status200OK)]
    public async Task<IActionResult> GetListAsync(CancellationToken cancellationToken)
    {
        var list = await reports.GetListAsync(cancellationToken);
        return Ok(new ApiResponse<StocktakeListDto>
        {
            Code = 0,
            Message = messages["Stocktake.ListLoaded"].Value,
            Data = list
        });
    }
}

using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using ZX.Platform.Identity.Api.AI.Queries;
using ZX.Platform.Identity.Api.Authorization;
using ZX.Platform.Identity.Api.Contracts;
using ZX.Platform.Identity.Api.Localization;
using ZX.Platform.Identity.Application.Authorization;
using ZX.Platform.Identity.Application.Menus;
using ZX.Platform.Identity.Application.Menus.Dtos;

namespace ZX.Platform.Identity.Api.Controllers;

[ApiController]
[Route("api/[controller]")]
[Authorize]
public sealed class MenusController(IMenuService menus, IApiMessageLocalizer messages) : ControllerBase
{
    [AiQuery(ResultShape = AiQueryResultShape.CompleteTree)]
    [HttpGet("getMenuTree")]
    [Authorize(Policy = IdentityPermissions.MenuRead)]
    [ProducesResponseType(typeof(ApiResponse<List<MenuDto>>), StatusCodes.Status200OK)]
    public async Task<IActionResult> GetTreeAsync(CancellationToken cancellationToken) => Ok(new ApiResponse<List<MenuDto>>
    { Code = 0, Message = messages["Access.MenuTreeLoaded"].Value, Data = await menus.GetTreeAsync(cancellationToken) });

    [AiQuery(ResultShape = AiQueryResultShape.CompleteTree)]
    [HttpGet("options")]
    [Authorize(Policy = PermissionPolicies.MenuOptions)]
    [ProducesResponseType(typeof(ApiResponse<List<MenuDto>>), StatusCodes.Status200OK)]
    public async Task<IActionResult> GetOptionsAsync(CancellationToken cancellationToken) => Ok(new ApiResponse<List<MenuDto>>
    { Code = 0, Message = messages["Access.MenuTreeLoaded"].Value, Data = await menus.GetTreeAsync(cancellationToken) });

    [AiQuery(ResultShape = AiQueryResultShape.CompleteList)]
    [HttpGet("permissions")]
    [Authorize(Policy = PermissionPolicies.MenuOptions)]
    [ProducesResponseType(typeof(ApiResponse<object>), StatusCodes.Status200OK)]
    public IActionResult GetPermissions() => Ok(new ApiResponse<object>
    {
        Code = 0, Message = messages["Access.PermissionListLoaded"].Value,
        Data = IdentityPermissions.All.Select(code => new { Code = code, Name = messages[$"Access.Permission.{code}"].Value }).ToArray()
    });

    [HttpPost("add")]
    [Authorize(Policy = IdentityPermissions.MenuCreate)]
    public async Task<IActionResult> CreateAsync(CreateMenuDto input, CancellationToken cancellationToken) =>
        StatusCode(StatusCodes.Status201Created, new ApiResponse<Guid>
        { Code = 0, Message = messages["Access.MenuCreated"].Value, Data = await menus.CreateAsync(input, cancellationToken) });

    [HttpPut("update")]
    [Authorize(Policy = IdentityPermissions.MenuUpdate)]
    public async Task<IActionResult> UpdateAsync(UpdateMenuDto input, CancellationToken cancellationToken)
    {
        await menus.UpdateAsync(input, cancellationToken);
        return Ok(new ApiResponse { Code = 0, Message = messages["Access.MenuUpdated"].Value });
    }

    [HttpPut("setEnabled")]
    [Authorize(Policy = IdentityPermissions.MenuChangeStatus)]
    public async Task<IActionResult> SetEnabledAsync([FromQuery] Guid id, [FromQuery] bool enabled, CancellationToken cancellationToken)
    {
        await menus.SetEnabledAsync(id, enabled, cancellationToken);
        return Ok(new ApiResponse { Code = 0, Message = messages["Access.MenuStatusUpdated"].Value });
    }

    [HttpPut("logicDelete")]
    [Authorize(Policy = IdentityPermissions.MenuDelete)]
    public async Task<IActionResult> DeleteAsync([FromQuery] Guid id, CancellationToken cancellationToken)
    {
        await menus.DeleteAsync(id, cancellationToken);
        return Ok(new ApiResponse { Code = 0, Message = messages["Access.MenuDeleted"].Value });
    }
}

using System.IdentityModel.Tokens.Jwt;
using System.Security.Claims;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using ZX.Platform.Identity.Api.AI.Queries;
using ZX.Platform.Identity.Api.Contracts;
using ZX.Platform.Identity.Api.Localization;
using ZX.Platform.Identity.Application.Authorization;
using ZX.Platform.Identity.Application.Roles;
using ZX.Platform.Identity.Application.Roles.Dtos;
using ZX.Platform.Identity.Application.Menus;
using ZX.Platform.Identity.Application.Menus.Dtos;

namespace ZX.Platform.Identity.Api.Controllers;

[ApiController]
[Route("api/[controller]")]
[Authorize]
public sealed class RolesController(IRoleService roles, IMenuService menus, IApiMessageLocalizer messages) : ControllerBase
{
    [AiQuery(ResultShape = AiQueryResultShape.CompleteList)]
    [HttpGet("getRoleList")]
    [Authorize(Policy = IdentityPermissions.RoleRead)]
    [ProducesResponseType(typeof(ApiResponse<List<RoleDto>>), StatusCodes.Status200OK)]
    public async Task<IActionResult> GetAllAsync(CancellationToken cancellationToken) => Ok(new ApiResponse<List<RoleDto>>
    {
        Code = 0, Message = messages["Access.RoleListLoaded"].Value, Data = await roles.GetAllAsync(cancellationToken)
    });

    // 用户分配角色只需要分配权限，不要求具备角色管理页面的读取权限。
    [AiQuery(ResultShape = AiQueryResultShape.CompleteList)]
    [HttpGet("options")]
    [Authorize(Policy = IdentityPermissions.UserAssignRoles)]
    [ProducesResponseType(typeof(ApiResponse<object>), StatusCodes.Status200OK)]
    public async Task<IActionResult> GetOptionsAsync(CancellationToken cancellationToken)
    {
        var list = await roles.GetAllAsync(cancellationToken);
        return Ok(new ApiResponse<object>
        {
            Code = 0, Message = messages["Access.RoleListLoaded"].Value,
            Data = list.Select(role => new { role.Id, role.Code, role.Name, role.IsEnabled, role.IsBuiltIn }).ToArray()
        });
    }

    [HttpPost("add")]
    [Authorize(Policy = IdentityPermissions.RoleCreate)]
    public async Task<IActionResult> CreateAsync(CreateRoleDto input, CancellationToken cancellationToken) =>
        StatusCode(StatusCodes.Status201Created, new ApiResponse<Guid>
        {
            Code = 0, Message = messages["Access.RoleCreated"].Value, Data = await roles.CreateAsync(input, cancellationToken)
        });

    [HttpPut("update")]
    [Authorize(Policy = IdentityPermissions.RoleUpdate)]
    public async Task<IActionResult> UpdateAsync(UpdateRoleDto input, CancellationToken cancellationToken)
    {
        await roles.UpdateAsync(input, cancellationToken);
        return Ok(new ApiResponse { Code = 0, Message = messages["Access.RoleUpdated"].Value });
    }

    [HttpPut("setRoleEnable")]
    [Authorize(Policy = IdentityPermissions.RoleChangeStatus)]
    public async Task<IActionResult> EnableAsync([FromQuery] Guid id, CancellationToken cancellationToken)
    {
        await roles.SetEnabledAsync(id, true, cancellationToken);
        return Ok(new ApiResponse { Code = 0, Message = messages["Access.RoleStatusUpdated"].Value });
    }

    [HttpPut("setRoleDisable")]
    [Authorize(Policy = IdentityPermissions.RoleChangeStatus)]
    public async Task<IActionResult> DisableAsync([FromQuery] Guid id, CancellationToken cancellationToken)
    {
        await roles.SetEnabledAsync(id, false, cancellationToken);
        return Ok(new ApiResponse { Code = 0, Message = messages["Access.RoleStatusUpdated"].Value });
    }

    [HttpPut("logicDelete")]
    [Authorize(Policy = IdentityPermissions.RoleDelete)]
    public async Task<IActionResult> DeleteAsync([FromQuery] Guid id, CancellationToken cancellationToken)
    {
        await roles.DeleteAsync(id, cancellationToken);
        return Ok(new ApiResponse { Code = 0, Message = messages["Access.RoleDeleted"].Value });
    }

    [AiQuery(ResultShape = AiQueryResultShape.CompleteList)]
    [HttpGet("permissions")]
    [Authorize(Policy = IdentityPermissions.RoleAssignPermissions)]
    [ProducesResponseType(typeof(ApiResponse<object>), StatusCodes.Status200OK)]
    public IActionResult GetPermissions() => Ok(new ApiResponse<object>
    {
        Code = 0, Message = messages["Access.PermissionListLoaded"].Value,
        Data = IdentityPermissions.All.Select(code => new
        {
            Code = code, Group = code.Split('.')[1],
            Name = messages[$"Access.Permission.{code}"].Value,
            GroupName = messages[$"Access.Group.{code.Split('.')[1]}"].Value
        }).ToArray()
    });

    [AiQuery(ResultShape = AiQueryResultShape.CompleteTree)]
    [HttpGet("permissionTree")]
    [Authorize(Policy = IdentityPermissions.RoleAssignPermissions)]
    [ProducesResponseType(typeof(ApiResponse<List<MenuDto>>), StatusCodes.Status200OK)]
    public async Task<IActionResult> GetPermissionTreeAsync(CancellationToken cancellationToken) => Ok(new ApiResponse<object>
    { Code = 0, Message = messages["Access.PermissionListLoaded"].Value, Data = await menus.GetPermissionTreeAsync(cancellationToken) });

    [HttpPut("updatePermissions")]
    [Authorize(Policy = IdentityPermissions.RoleAssignPermissions)]
    public async Task<IActionResult> UpdatePermissionsAsync(UpdateRolePermissionsDto input, CancellationToken cancellationToken)
    {
        await roles.UpdatePermissionsAsync(input, cancellationToken);
        return Ok(new ApiResponse { Code = 0, Message = messages["Access.PermissionsUpdated"].Value });
    }

    [AiQuery(ResultShape = AiQueryResultShape.CompleteList)]
    [HttpGet("userRoles")]
    [Authorize(Policy = IdentityPermissions.UserAssignRoles)]
    [ProducesResponseType(typeof(ApiResponse<List<Guid>>), StatusCodes.Status200OK)]
    public async Task<IActionResult> GetUserRolesAsync([FromQuery] Guid userId, CancellationToken cancellationToken) => Ok(new ApiResponse<List<Guid>>
    {
        Code = 0, Message = messages["Access.UserRolesLoaded"].Value, Data = await roles.GetUserRolesAsync(userId, cancellationToken)
    });

    [HttpPut("updateUserRoles")]
    [Authorize(Policy = IdentityPermissions.UserAssignRoles)]
    public async Task<IActionResult> UpdateUserRolesAsync(UpdateUserRolesDto input, CancellationToken cancellationToken)
    {
        await roles.UpdateUserRolesAsync(Guid.Parse(User.FindFirstValue(JwtRegisteredClaimNames.Sub)!), input, cancellationToken);
        return Ok(new ApiResponse { Code = 0, Message = messages["Access.UserRolesUpdated"].Value });
    }
}

using Microsoft.AspNetCore.Mvc;
using ZX.Platform.Identity.Api.AI.Queries;
using ZX.Platform.Identity.Api.Contracts;
using ZX.Platform.Identity.Api.Localization;
using ZX.Platform.Identity.Application.Sbus;
using ZX.Platform.Identity.Application.Sbus.Dtos;

using Microsoft.AspNetCore.Authorization;
using ZX.Platform.Identity.Api.Authorization;
using ZX.Platform.Identity.Application.Authorization;

namespace ZX.Platform.Identity.Api.Controllers
{
    [Route("api/[controller]")]
    [ApiController]
    [Authorize]
    public class SbusController : ControllerBase
    {
        private readonly ISbuService _sbuService;
        private readonly IApiMessageLocalizer _messages;

        public SbusController(ISbuService sbuService, IApiMessageLocalizer messages)
        {
            _sbuService = sbuService;
            _messages = messages;
        }

        [HttpPost("add")]
        [Authorize(Policy = IdentityPermissions.SbuCreate)]
        public async Task<IActionResult> CreateAsync([FromBody] CreateSbuDto createSbu, CancellationToken cancellationToken)
        {
            var sbuId = await _sbuService.CreateAsync(createSbu, cancellationToken);
            var response = new ApiResponse<Guid>
            {
                Code = 0,
                Message = _messages["Sbu.Created"].Value,
                Data = sbuId
            };
            return StatusCode(StatusCodes.Status201Created, response);
        }

        [AiQuery]
        [HttpGet("getSbu")]
        [Authorize(Policy = IdentityPermissions.SbuRead)]
        [ProducesResponseType(typeof(ApiResponse<SbuDetailDto>), StatusCodes.Status200OK)]
        public async Task<IActionResult> GetByIdAsync([FromQuery] Guid id, CancellationToken cancellationToken)
        {
            var sbu = await _sbuService.GetByIdAsync(id, cancellationToken);
            var response = new ApiResponse<SbuDetailDto>
            {
                Code = 0,
                Message = _messages["Sbu.DetailsLoaded"].Value,
                Data = sbu
            };
            return StatusCode(StatusCodes.Status200OK, response);
        }

        [AiQuery(ResultShape = AiQueryResultShape.CompleteList)]
        [HttpGet("getSbuList")]
        [Authorize(Policy = IdentityPermissions.SbuRead)]
        [ProducesResponseType(typeof(ApiResponse<List<SbuDetailDto>>), StatusCodes.Status200OK)]
        public async Task<IActionResult> GetAllAsync(CancellationToken cancellationToken)
        {
            var sbus = await _sbuService.GetAllAsync(cancellationToken);
            var response = new ApiResponse<List<SbuDetailDto>>
            {
                Code = 0,
                Message = _messages["Sbu.ListLoaded"].Value,
                Data = sbus
            };
            return StatusCode(StatusCodes.Status200OK, response);
        }

        [HttpPut("updateName")]
        [Authorize(Policy = IdentityPermissions.SbuRename)]
        public async Task<IActionResult> UpdateNameAsync([FromBody] UpdateSbuNameDto updateSbuName, CancellationToken cancellationToken)
        {
            await _sbuService.UpdateNameAsync(updateSbuName, cancellationToken);
            var response = new ApiResponse
            {
                Code = 0,
                Message = _messages["Sbu.NameUpdated"].Value
            };
            return StatusCode(StatusCodes.Status200OK, response);
        }

        [HttpPut("setSbuEnable")]
        [Authorize(Policy = IdentityPermissions.SbuChangeStatus)]
        public async Task<IActionResult> SetSbuEnableAsync([FromQuery] Guid id, CancellationToken cancellationToken)
        {
            await _sbuService.SetSbuEnableAsync(id, cancellationToken);
            var response = new ApiResponse
            {
                Code = 0,
                Message = _messages["Sbu.StatusUpdated"].Value
            };
            return StatusCode(StatusCodes.Status200OK, response);
        }

        [HttpPut("setSbuDisable")]
        [Authorize(Policy = IdentityPermissions.SbuChangeStatus)]
        public async Task<IActionResult> SetSbuDisableAsync([FromQuery] Guid id, CancellationToken cancellationToken)
        {
            await _sbuService.SetSbuDisableAsync(id, cancellationToken);
            var response = new ApiResponse
            {
                Code = 0,
                Message = _messages["Sbu.StatusUpdated"].Value
            };
            return StatusCode(StatusCodes.Status200OK, response);
        }

        [HttpPut("logicDelete")]
        [Authorize(Policy = IdentityPermissions.SbuDelete)]
        public async Task<IActionResult> SoftDeleteAsync([FromQuery] Guid id, CancellationToken cancellationToken)
        {
            await _sbuService.SoftDeleteAsync(id, cancellationToken);
            var response = new ApiResponse
            {
                Code = 0,
                Message = _messages["Sbu.Deleted"].Value
            };
            return StatusCode(StatusCodes.Status200OK, response);
        }

        [HttpPut("restore")]
        [Authorize(Policy = IdentityPermissions.SbuRestore)]
        public async Task<IActionResult> RestoreAsync([FromQuery] Guid id, CancellationToken cancellationToken)
        {
            await _sbuService.RestoreAsync(id, cancellationToken);
            var response = new ApiResponse
            {
                Code = 0,
                Message = _messages["Sbu.Restored"].Value
            };
            return StatusCode(StatusCodes.Status200OK, response);
        }

        [AiQuery(ResultShape = AiQueryResultShape.CompleteList)]
        [HttpGet("getAllEnabledSbus")]
        [Authorize(Policy = PermissionPolicies.SbuOptions)]
        [ProducesResponseType(typeof(ApiResponse<List<SbuDetailDto>>), StatusCodes.Status200OK)]
        public async Task<IActionResult> GetAllEnabledSbusAsync(CancellationToken cancellationToken)
        {
            var sbus = await _sbuService.GetAllEnabledSbusAsync(cancellationToken);
            var response = new ApiResponse<List<SbuDetailDto>>
            {
                Code = 0,
                Message = _messages["Sbu.EnabledListLoaded"].Value,
                Data = sbus
            };
            return StatusCode(StatusCodes.Status200OK, response);
        }
    }
}

using Microsoft.AspNetCore.Mvc;
using ZX.Platform.Identity.Api.Contracts;
using ZX.Platform.Identity.Api.AI.Queries;
using ZX.Platform.Identity.Api.Localization;
using ZX.Platform.Identity.Application.Users;
using ZX.Platform.Identity.Application.Users.Dtos;

using System.Security.Claims;
using System.IdentityModel.Tokens.Jwt;
using Microsoft.AspNetCore.Authorization;
using ZX.Platform.Identity.Api.Authentication;
using ZX.Platform.Identity.Application.Authorization;
using ZX.Platform.Identity.Application.Roles;

namespace ZX.Platform.Identity.Api.Controllers
{
    [Route("api/[controller]")]
    [ApiController]
    [Authorize]
    public class UsersController : ControllerBase
    {
        private readonly IUserService _userService;
        private readonly IApiMessageLocalizer _messages;
        private readonly IPermissionService _permissions;
        private readonly IRoleService _roles;

        public UsersController(IUserService userService, IApiMessageLocalizer messages, IPermissionService permissions, IRoleService roles)
        {
            _userService = userService;
            _messages = messages;
            _permissions = permissions;
            _roles = roles;
        }

        [HttpPost("add")]
        [Authorize(Policy = IdentityPermissions.UserCreate)]
        public async Task<IActionResult> CreateAsync([FromBody] CreateUserDto createUser, CancellationToken cancellationToken)
        {
            var userId = await _userService.CreateAsync(createUser, cancellationToken);
            var response = new ApiResponse<Guid>
            {
                Code = 0,
                Message = _messages["User.Created"].Value,
                Data = userId
            };
            return StatusCode(StatusCodes.Status201Created, response);
        }

        [AiQuery]
        [HttpGet("getUser")]
        [Authorize(Policy = IdentityPermissions.UserRead)]
        [ProducesResponseType(typeof(ApiResponse<UserDetailDto>), StatusCodes.Status200OK)]
        public async Task<IActionResult> GetByIdAsync([FromQuery] Guid id, CancellationToken cancellationToken)
        {
            var user = await _userService.GetByIdAsync(id, cancellationToken);
            var response = new ApiResponse<UserDetailDto>
            {
                Code = 0,
                Message = _messages["User.DetailsLoaded"].Value,
                Data = user
            };
            return StatusCode(StatusCodes.Status200OK, response);
        }

        [AiQuery]
        [HttpGet("getUserList")]
        [Authorize(Policy = IdentityPermissions.UserRead)]
        [ProducesResponseType(typeof(ApiResponse<UserPageDto>), StatusCodes.Status200OK)]
        public async Task<IActionResult> GetPageListAsync([FromQuery] UserQueryDto userQuery, CancellationToken cancellationToken)
        {
            var (users, count) = await _userService.GetPageListAsync(userQuery, cancellationToken);
            var response = new ApiResponse<UserPageDto>
            {
                Code = 0,
                Message = _messages["User.ListLoaded"].Value,
                Data = new UserPageDto
                {
                    List = users,
                    Total = count
                }
            };
            return StatusCode(StatusCodes.Status200OK, response);
        }

        [HttpPut("updateDisplayName")]
        public async Task<IActionResult> UpdateDisplayNameAsync([FromBody] UpdateUserDisplayNameDto updateUserDisplayName, CancellationToken cancellationToken)
        {
            if (updateUserDisplayName.Id != Guid.Parse(User.FindFirstValue(JwtRegisteredClaimNames.Sub)!) &&
                !await _permissions.HasAsync(CurrentUserId, IdentityPermissions.UserRename, cancellationToken))
                return Forbid();

            await _userService.UpdateDisplayNameAsync(updateUserDisplayName, cancellationToken);
            var response = new ApiResponse
            {
                Code = 0,
                Message = _messages["User.DisplayNameUpdated"].Value
            };
            return StatusCode(StatusCodes.Status200OK, response);
        }

        [HttpPut("setUserEnable")]
        [Authorize(Policy = IdentityPermissions.UserChangeStatus)]
        public async Task<IActionResult> SetUserEnableAsync([FromQuery] Guid id, CancellationToken cancellationToken)
        {
            await _userService.SetUserEnableAsync(id, cancellationToken);
            var response = new ApiResponse
            {
                Code = 0,
                Message = _messages["User.StatusUpdated"].Value
            };
            return StatusCode(StatusCodes.Status200OK, response);
        }

        [HttpPut("setUserDisable")]
        [Authorize(Policy = IdentityPermissions.UserChangeStatus)]
        public async Task<IActionResult> SetUserDisableAsync([FromQuery] Guid id, CancellationToken cancellationToken)
        {
            await _roles.EnsureCanDeactivateUsersAsync(CurrentUserId, [id], cancellationToken);
            await _userService.SetUserDisableAsync(id, cancellationToken);
            var response = new ApiResponse
            {
                Code = 0,
                Message = _messages["User.StatusUpdated"].Value
            };
            return StatusCode(StatusCodes.Status200OK, response);
        }

        [HttpPost("forceLogout")]
        [Authorize(Policy = IdentityPermissions.UserForceLogout)]
        public async Task<IActionResult> ForceLogoutAsync([FromQuery] Guid id, CancellationToken cancellationToken)
        {
            await _userService.ForceLogoutAsync(id, cancellationToken);
            var response = new ApiResponse
            {
                Code = 0,
                Message = _messages["Auth.ForcedLogout"].Value
            };
            return StatusCode(StatusCodes.Status200OK, response);
        }

        [HttpPut("logicDelete")]
        [Authorize(Policy = IdentityPermissions.UserDelete)]
        public async Task<IActionResult> SoftDeleteAsync([FromQuery] Guid id, CancellationToken cancellationToken)
        {
            await _roles.EnsureCanDeactivateUsersAsync(CurrentUserId, [id], cancellationToken);
            await _userService.SoftDeleteAsync(id, cancellationToken);
            var response = new ApiResponse
            {
                Code = 0,
                Message = _messages["User.Deleted"].Value
            };
            return StatusCode(StatusCodes.Status200OK, response);
        }

        [HttpPut("restore")]
        [Authorize(Policy = IdentityPermissions.UserRestore)]
        public async Task<IActionResult> RestoreAsync([FromQuery] Guid id, CancellationToken cancellationToken)
        {
            await _userService.RestoreAsync(id, cancellationToken);
            var response = new ApiResponse
            {
                Code = 0,
                Message = _messages["User.Restored"].Value
            };
            return StatusCode(StatusCodes.Status200OK, response);
        }

        [HttpPut("updateUserSbus")]
        [Authorize(Policy = IdentityPermissions.UserAssignSbus)]
        public async Task<IActionResult> UpdateUserSbusAsync([FromBody] UpdateUserSbuDto updateUserSbu, CancellationToken cancellationToken)
        {
            await _userService.UpdateUserSbusAsync(updateUserSbu, cancellationToken);
            var response = new ApiResponse
            {
                Code = 0,
                Message = _messages["User.SbusUpdated"].Value
            };
            return StatusCode(StatusCodes.Status200OK, response);
        }

        [HttpPut("batchDelete")]
        [Authorize(Policy = IdentityPermissions.UserDelete)]
        public async Task<IActionResult> BatchDeleteAsync([FromBody] List<Guid> guids, CancellationToken cancellationToken)
        {
            await _roles.EnsureCanDeactivateUsersAsync(CurrentUserId, guids, cancellationToken);
            await _userService.BatchDeleteAsync(guids, cancellationToken);
            var response = new ApiResponse
            {
                Code = 0,
                Message = _messages["User.BatchDeleted"].Value
            };
            return StatusCode(StatusCodes.Status200OK, response);
        }
        private Guid CurrentUserId => Guid.Parse(User.FindFirstValue(JwtRegisteredClaimNames.Sub)!);

        /// <summary>
        /// 管理员按工号只读查询目录，用于预开通前核对。不接收员工密码、不创建用户。
        /// </summary>
        [AiQuery]
        [HttpGet("ldapLookup")]
        [Authorize(Policy = IdentityPermissions.UserCreate)]
        [ProducesResponseType(typeof(ApiResponse<LdapUserLookupResultDto>), StatusCodes.Status200OK)]
        public async Task<IActionResult> LdapLookupAsync([FromQuery] LdapUserLookupQueryDto query, CancellationToken cancellationToken)
        {
            var result = await _userService.LdapLookupAsync(query, cancellationToken);
            // 个人目录资料不缓存。
            Response.Headers.CacheControl = "no-store";
            var response = new ApiResponse<LdapUserLookupResultDto>
            {
                Code = 0,
                Message = _messages[result.Found ? "User.LdapUserFound" : "User.LdapUserNotFound"].Value,
                Data = result
            };
            return StatusCode(StatusCodes.Status200OK, response);
        }

        /// <summary>
        /// 预开通 OA 用户：仅创建待审批记录，或一次完成创建、审批和授权。
        /// </summary>
        [HttpPost("addLdap")]
        [Authorize(Policy = IdentityPermissions.UserCreate)]
        public async Task<IActionResult> AddLdapAsync([FromBody] CreateLdapUserDto input, CancellationToken cancellationToken)
        {
            var created = await _userService.CreateLdapAsync(CurrentUserId, input, cancellationToken);
            var response = new ApiResponse<LdapUserCreatedDto>
            {
                Code = 0,
                Message = _messages[created.ApprovalStatus == ZX.Platform.Identity.Domain.Entities.UserApprovalStatus.Approved
                    ? "User.LdapUserProvisioned"
                    : "User.LdapUserPendingCreated"].Value,
                Data = created
            };
            return StatusCode(StatusCodes.Status201Created, response);
        }

        /// <summary>
        /// 审批通过 OA 账号，并在同一事务中分配角色和 SBU。
        /// </summary>
        [HttpPut("approveLdap")]
        [Authorize(Policy = IdentityPermissions.UserApprove)]
        public async Task<IActionResult> ApproveLdapAsync([FromBody] ApproveLdapUserDto input, CancellationToken cancellationToken)
        {
            await _userService.ApproveLdapAsync(CurrentUserId, input, cancellationToken);
            var response = new ApiResponse
            {
                Code = 0,
                Message = _messages["User.LdapUserApproved"].Value
            };
            return StatusCode(StatusCodes.Status200OK, response);
        }

        /// <summary>
        /// 拒绝 OA 开通申请。已开通账号必须走禁用流程。
