using ZX.Platform.Identity.Domain.Auditing;
using ZX.Platform.Identity.Domain.Exceptions;

namespace ZX.Platform.Identity.Domain.Entities
{
    public sealed class User : SoftDeletableEntity
    {
        private User()
        {
        }

        private User(
            Guid id,
            string account,
            string displayName,
            string? passwordHash,
            string authType,
            string approvalStatus,
            bool isEnabled)
        {
            Id = id;
            Account = account;
            NormalizedAccount = account.ToUpperInvariant();
            DisplayName = displayName;
            PasswordHash = passwordHash;
            AuthType = authType;
            ApprovalStatus = approvalStatus;
            IsEnabled = isEnabled;
            SecurityVersion = 1;
        }

        /// <summary>
        /// 用户唯一标识
        /// </summary>
        public Guid Id { get; private set; }

        /// <summary>
        /// 用户登录账号。本地账号由管理员指定，OA 账号与工号一致。
        /// </summary>
        public string Account { get; private set; } = string.Empty;

        /// <summary>
        /// 标准化账号，用于账号查询和唯一性比较
        /// </summary>
        public string NormalizedAccount { get; private set; } = string.Empty;

        /// <summary>
        /// 用户显示名称
        /// </summary>
        public string DisplayName { get; private set; } = string.Empty;

        /// <summary>
        /// 经过安全哈希处理后的密码，不能保存明文密码。
        /// 本地账号必须有值，OA 账号必须为空。
        /// </summary>
        public string? PasswordHash { get; private set; }

        /// <summary>
        /// 认证来源，见 <see cref="UserAuthType"/>。
        /// </summary>
        public string AuthType { get; private set; } = UserAuthType.Local;

        /// <summary>
        /// OA 工号；本地账号为空。按字符串保存，保留前导零。
        /// </summary>
        public string? EmployeeNo { get; private set; }

        /// <summary>
        /// 目录来源标识；更换该值等同于更换身份命名空间，不能随部署修改。
        /// </summary>
        public string? LdapProvider { get; private set; }

        /// <summary>
        /// 规范化后的目录唯一标识（AD objectGUID）。
        /// </summary>
        public string? LdapSubject { get; private set; }

        /// <summary>
        /// 开通审批状态，见 <see cref="UserApprovalStatus"/>。
        /// </summary>
        public string ApprovalStatus { get; private set; } = UserApprovalStatus.Approved;

        /// <summary>
        /// 会话安全版本。审批、拒绝、启用、禁用、删除、恢复和本地改密时递增，
        /// 用于使旧会话失效并作为账户状态变更的乐观并发检查。
        /// </summary>
        public long SecurityVersion { get; private set; } = 1;

        /// <summary>
        /// 最近一次审批或拒绝的操作人。
        /// </summary>
        public Guid? ReviewedByUserId { get; private set; }

        /// <summary>
        /// 最近一次审批或拒绝的 UTC 时间。
        /// </summary>
        public DateTimeOffset? ReviewedAtUtc { get; private set; }

        /// <summary>
        /// 最近一次审批说明或拒绝原因。
        /// </summary>
        public string? ReviewReason { get; private set; }

        /// <summary>
        /// 用户是否启用
        /// </summary>
        public bool IsEnabled { get; private set; }

        /// <summary>
        /// 连续登录失败次数
        /// </summary>
        public int AccessFailedCount { get; private set; }

        /// <summary>
        /// 账户锁定结束时间；为空表示当前没有锁定时间
        /// </summary>
        public DateTimeOffset? LockoutEndUtc { get; private set; }

        /// <summary>
        /// 是否为 OA 员工账号。
        /// </summary>
        public bool IsLdap => AuthType == UserAuthType.Ldap;

        /// <summary>
        /// 是否允许在 ZX 修改密码；OA 账号的密码只能在 OA 修改。
        /// </summary>
        public bool CanChangePassword => AuthType == UserAuthType.Local;

        /// <summary>账号状态允许维持登录；待审批 OA 账号只有系统外壳访问权。</summary>
        public bool CanUseSession => !IsDeleted && IsEnabled &&
            (ApprovalStatus == UserApprovalStatus.Approved ||
             (IsLdap && ApprovalStatus == UserApprovalStatus.Pending));

        /// <summary>业务授权资格；待审批账号即使存在角色或 SBU 关联也不得生效。</summary>
        public bool HasBusinessAccess => !IsDeleted && IsEnabled && ApprovalStatus == UserApprovalStatus.Approved;

        /// <summary>
        /// 创建本地管理账号。本地账号必须有密码哈希，审批状态固定为通过。
        /// </summary>
        public static User CreateLocal(
            string account,
            string displayName,
            string passwordHash)
        {
            ArgumentException.ThrowIfNullOrWhiteSpace(account);
            ArgumentException.ThrowIfNullOrWhiteSpace(displayName);
            ArgumentException.ThrowIfNullOrWhiteSpace(passwordHash);

            return new User(
                Guid.NewGuid(),
                account.Trim(),
                displayName.Trim(),
                passwordHash,
                UserAuthType.Local,
                UserApprovalStatus.Approved,
                true);
        }

        /// <summary>
        /// 创建待业务审批的 OA 员工账号。允许登录，不保存密码、不分配角色和 SBU。
        /// </summary>
        /// <param name="account">
        /// ZX 账号，固定使用工号；目录登录名（如 sAMAccountName）只用于目录认证，不作为 ZX 账号。
        /// </param>
        public static User CreateLdap(
            string account,
            string employeeNo,
            string displayName,
            string provider,
            string subject)
        {
            ArgumentException.ThrowIfNullOrWhiteSpace(account);
            ArgumentException.ThrowIfNullOrWhiteSpace(employeeNo);
            ArgumentException.ThrowIfNullOrWhiteSpace(displayName);
            ArgumentException.ThrowIfNullOrWhiteSpace(provider);
            ArgumentException.ThrowIfNullOrWhiteSpace(subject);

            var user = new User(
                Guid.NewGuid(),
                account.Trim(),
                displayName.Trim(),
                null,
                UserAuthType.Ldap,
                UserApprovalStatus.Pending,
                true);
            user.EmployeeNo = employeeNo.Trim();
            user.LdapProvider = provider.Trim();
            user.LdapSubject = subject.Trim();
            return user;
        }

        /// <summary>
        /// 审批通过 OA 业务访问。角色和 SBU 由调用方在同一事务中写入。
        /// Pending 的禁用状态保留；Rejected 的显式重新审批恢复启用。
        /// </summary>
        /// <param name="reviewerUserId">审批人；匿名的首次申请由管理员后续审批，不能为空。</param>
        /// <param name="reviewedAtUtc">审批时间，统一使用 UTC。</param>
        /// <param name="reason">审批说明，可为空。</param>
        public void ApproveLdap(Guid reviewerUserId, DateTimeOffset reviewedAtUtc, string? reason)
        {
            EnsureLdapAccount();
            // 已通过的账号一律不能再次审批：否则“已通过但被禁用”可以借审批重新启用，
            // 绕过 identity.user.status 的启用权限，并顺带改写既有角色。
            // 重新启用必须走 Enable()。
            if (ApprovalStatus == UserApprovalStatus.Approved)
                throw new DomainException("User.AlreadyApproved");

            if (ApprovalStatus == UserApprovalStatus.Rejected)
                IsEnabled = true;
            ApprovalStatus = UserApprovalStatus.Approved;
            ReviewedByUserId = reviewerUserId;
            ReviewedAtUtc = reviewedAtUtc;
            ReviewReason = NormalizeReason(reason);
            IncrementSecurityVersion();
        }

        /// <summary>
        /// 拒绝 OA 开通申请，保持禁用。已开通账号必须走禁用流程，不能改成拒绝。
        /// </summary>
        public void RejectLdap(Guid reviewerUserId, DateTimeOffset reviewedAtUtc, string? reason)
        {
            EnsureLdapAccount();
            if (ApprovalStatus == UserApprovalStatus.Approved)
                throw new DomainException("User.AlreadyApproved");

            ApprovalStatus = UserApprovalStatus.Rejected;
            IsEnabled = false;
            ReviewedByUserId = reviewerUserId;
            ReviewedAtUtc = reviewedAtUtc;
            ReviewReason = NormalizeReason(reason);
            IncrementSecurityVersion();
        }

        /// <summary>
        /// 修改用户显示名称。显示名称不影响登录资格，不递增安全版本。
        /// </summary>
        public void ChangeDisplayName(string displayName)
        {
            ArgumentException.ThrowIfNullOrWhiteSpace(displayName);
            DisplayName = displayName.Trim();
        }

        /// <summary>
        /// 修改密码哈希，并清除原有登录失败和锁定状态。
        /// OA 账号的密码由目录维护，不允许在这里写入。
        /// </summary>
        public void ChangePasswordHash(string passwordHash)
        {
            ArgumentException.ThrowIfNullOrWhiteSpace(passwordHash);
            if (!CanChangePassword)
                throw new DomainException("Auth.PasswordChangeNotAllowedForLdap");

            PasswordHash = passwordHash;
            RecordLoginSuccess();
            IncrementSecurityVersion();
        }

        /// <summary>
        /// 启用用户。待审批 OA 账号可登录但没有业务权限；已拒绝账号必须重新审批。
        /// </summary>
        public void Enable()
        {
            if (IsDeleted)
                throw new DomainException("User.RestoreBeforeEnable");
            if (IsEnabled)
                return;
            if (IsLdap && ApprovalStatus == UserApprovalStatus.Rejected)
                throw new DomainException("User.RejectedCannotEnable");

            IsEnabled = true;
            IncrementSecurityVersion();
        }

        /// <summary>
        /// 禁用用户。
        /// </summary>
        public void Disable()
        {
            if (!IsEnabled)
                return;

            IsEnabled = false;
            IncrementSecurityVersion();
        }

        /// <summary>
        /// 判断用户在指定时间是否处于锁定状态
        /// </summary>
        public bool IsLocked(DateTimeOffset now) =>
            LockoutEndUtc.HasValue && LockoutEndUtc.Value > now;

        /// <summary>
        /// 判断用户当前是否允许登录：状态允许维持会话且未被锁定。
        /// </summary>
        public bool CanLogin(DateTimeOffset now) =>
            CanUseSession && !IsLocked(now);

        /// <summary>
        /// 记录一次登录失败，达到限制后锁定账户
        /// </summary>
        public void RecordLoginFailure(
            DateTimeOffset now,
            int maximumFailedAttempts,
            TimeSpan lockoutDuration)
        {
            ArgumentOutOfRangeException.ThrowIfLessThan(maximumFailedAttempts, 1);

            if (lockoutDuration <= TimeSpan.Zero)
                throw new ArgumentOutOfRangeException(nameof(lockoutDuration));

            if (LockoutEndUtc.HasValue && LockoutEndUtc.Value <= now)
                RecordLoginSuccess();

            AccessFailedCount++;

            if (AccessFailedCount >= maximumFailedAttempts)
                LockoutEndUtc = now.Add(lockoutDuration);
        }

        /// <summary>
        /// 记录登录成功，并清除登录失败和锁定状态
        /// </summary>
        public void RecordLoginSuccess()
        {
            AccessFailedCount = 0;
            LockoutEndUtc = null;
        }

        /// <summary>
        /// 逻辑删除时触发
        /// </summary>
        protected override void OnDeleted()
        {
            IsEnabled = false;
            IncrementSecurityVersion();
        }

        /// <summary>
        /// 逻辑删除恢复时触发。只恢复原有身份和审批状态，不自动开通 OA 账号。
        /// </summary>
        protected override void OnRestored()
        {
            if (!IsLdap)
                IsEnabled = true;
            IncrementSecurityVersion();
        }

        private void EnsureLdapAccount()
        {
            if (!IsLdap)
                throw new DomainException("User.NotLdapAccount");
            if (IsDeleted)
                throw new DomainException("User.DeletedCannotReview");
        }

        private void IncrementSecurityVersion() => SecurityVersion++;

        private static string? NormalizeReason(string? reason)
        {
            var trimmed = reason?.Trim();
            return string.IsNullOrEmpty(trimmed) ? null : trimmed;
        }
    }
}

using ZX.Platform.Identity.Domain.Auditing;

namespace ZX.Platform.Identity.Domain.Entities;

/// <summary>
/// OA 账号审批事件。只追加不修改，保留预开通、通过、拒绝与重新审核的完整轨迹。
/// 用户表上的 ReviewedBy / ReviewedAt / ReviewReason 只反映最近一次审核，
/// 重新审核会覆盖旧值，不能当作审批历史。
/// </summary>
public sealed class UserApprovalAudit : AuditableEntity
{
    private UserApprovalAudit() { }

    public Guid Id { get; private set; }

    public Guid TargetUserId { get; private set; }

    /// <summary>目标账号快照：账号可能改名，审计要保留当时的值。</summary>
    public string TargetAccount { get; private set; } = string.Empty;

    public string TargetEmployeeNo { get; private set; } = string.Empty;

    /// <summary>取值见 <see cref="UserApprovalActions"/>。</summary>
    public string Action { get; private set; } = string.Empty;

    /// <summary>审批前状态；首次创建时为 None。</summary>
    public string FromStatus { get; private set; } = string.Empty;

    public string ToStatus { get; private set; } = string.Empty;

    public Guid ActorUserId { get; private set; }

    public string? Reason { get; private set; }

    /// <summary>
    /// 本次审批写入的角色与 SBU 快照，逗号分隔的 32 位 GUID。
    /// 按 CLOB 保存：数量由业务权限决定，不能因为审计字段长度而限制授权或截断证据。
    /// </summary>
    public string? RoleIds { get; private set; }

    public string? SbuIds { get; private set; }

    /// <summary>调用链标识，便于和日志、追踪系统对齐。</summary>
    public string? TraceId { get; private set; }

    public static UserApprovalAudit CreateForNoneStatus(
        User user, string action, Guid actorUserId, string? reason,
        IEnumerable<Guid> roleIds, IEnumerable<Guid> sbuIds, string? traceId) =>
        Create(user, action, "None", actorUserId, reason, roleIds, sbuIds, traceId);

    public static UserApprovalAudit Create(
        User user,
        string action,
        string fromStatus,
        Guid actorUserId,
        string? reason,
        IEnumerable<Guid> roleIds,
        IEnumerable<Guid> sbuIds,
        string? traceId)
    {
        ArgumentNullException.ThrowIfNull(user);
        ArgumentException.ThrowIfNullOrWhiteSpace(action);
        // 审批审计只针对带工号的 OA 账号。Oracle 把空串当 NULL，而 TARGET_EMPLOYEE_NO 是
        // NOT NULL，缺工号时会在写库阶段才报 ORA-01400；这里提前拒绝，错误位置更准确。
        ArgumentException.ThrowIfNullOrWhiteSpace(user.EmployeeNo);

        return new UserApprovalAudit
        {
            Id = Guid.NewGuid(),
            TargetUserId = user.Id,
            TargetAccount = user.Account,
            TargetEmployeeNo = user.EmployeeNo!,
            Action = action,
            FromStatus = fromStatus,
            // 取落库后的实际状态，避免事件与实体不一致。
            ToStatus = user.ApprovalStatus,
            ActorUserId = actorUserId,
            Reason = string.IsNullOrWhiteSpace(reason) ? null : reason.Trim(),
            RoleIds = Join(roleIds),
            SbuIds = Join(sbuIds),
            TraceId = string.IsNullOrWhiteSpace(traceId) ? null : traceId.Trim()
        };
    }

    private static string? Join(IEnumerable<Guid> ids)
    {
        var values = ids.Distinct().Select(id => id.ToString("N")).ToList();
        return values.Count == 0 ? null : string.Join(',', values);
    }
}

/// <summary>
/// 审批事件类型。ReApproved 表示被拒绝后重新审核通过，与首次审批区分开。
/// </summary>
public static class UserApprovalActions
{
    /// <summary>预开通：管理员在用户不存在时按工号建档。</summary>
    public const string Provisioned = "Provisioned";

    public const string Approved = "Approved";

    public const string Rejected = "Rejected";

    public const string ReApproved = "ReApproved";
}

namespace ZX.Platform.Identity.Domain.Entities
{
    /// <summary>
    /// OA 账号开通审批状态。本地账号固定为 Approved。
    /// </summary>
    public static class UserApprovalStatus
    {
        /// <summary>
        /// 待业务授权。已启用时可登录系统，但没有有效角色、权限、菜单和 SBU。
        /// </summary>
        public const string Pending = "Pending";

        /// <summary>
        /// 业务审批通过，分配的角色和 SBU 可以生效；登录仍受启停用状态控制。
        /// </summary>
        public const string Approved = "Approved";

        /// <summary>
        /// 申请被拒绝，重复登录不会自动回到待审批。
        /// </summary>
        public const string Rejected = "Rejected";

        public static IReadOnlyList<string> All { get; } = [Pending, Approved, Rejected];

        public static bool IsValid(string? value) => value is Pending or Approved or Rejected;
    }
