import type { DataTableColumn } from './types'
import { getTableExportData, saveExportFile } from './exportUtils'

const escapeCell = (value: unknown) => {
  let text = value instanceof Date ? value.toISOString() : String(value ?? '')
  // Treat formula-like strings as text when a spreadsheet opens the CSV.
  if (typeof value === 'string' && (/^[=+\-@]/.test(text.trimStart()) || /^[\t\r\n]/.test(text))) {
    text = `'${text}`
  }
  return `"${text.replace(/"/g, '""')}"`
}

/** Export exactly the supplied rows and visible data columns, without requesting more data. */
export const exportTableCsv = <T extends object>(
  data: readonly T[],
  columns: readonly DataTableColumn<T>[],
  fileName: string,
) => {
  const { headers, rows } = getTableExportData(data, columns)
  if (!rows.length || !headers.length) return
  const lines = [headers, ...rows].map((row) => row.map(escapeCell).join(','))

  const blob = new Blob(['\uFEFF', lines.join('\r\n')], { type: 'text/csv;charset=utf-8;' })
  saveExportFile(blob, fileName, 'csv')
}

import type { DataTableColumn, DataTableExportFormat, DataTableExportValue } from './types'
import { downloadBlob, sanitizeFileName } from '@/utils/download'

const getFieldValue = (row: object, prop: string): unknown =>
  prop.split('.').reduce<unknown>((value, key) => {
    if (typeof value !== 'object' || value === null) return undefined
    return Reflect.get(value, key)
  }, row)

const normalizeValue = (value: unknown): DataTableExportValue => {
  if (value === null || value === undefined) return null
  if (typeof value === 'string' || typeof value === 'boolean') return value
  if (typeof value === 'number' && Number.isFinite(value)) return value
  if (value instanceof Date && Number.isFinite(value.getTime())) return new Date(value.getTime())
  // Keep arbitrary objects out of ExcelJS's formula, hyperlink and rich-text cell APIs.
  return String(value)
}

export const getExportColumns = <T extends object>(columns: readonly DataTableColumn<T>[]) =>
  columns.filter(
    (column) =>
      (!column.type || column.type === 'default') &&
      column.exportable !== false &&
      Boolean(column.prop || column.exportValue),
  )

export const getTableExportData = <T extends object>(
  data: readonly T[],
  columns: readonly DataTableColumn<T>[],
) => {
  const exportColumns = getExportColumns(columns)
  return {
    headers: exportColumns.map((column) => column.label || column.prop || ''),
    rows: data.map((row, index) =>
      exportColumns.map((column) =>
        normalizeValue(
          column.exportValue
            ? column.exportValue(row, index)
            : column.prop
              ? getFieldValue(row, column.prop)
              : null,
        ),
      ),
    ),
  }
}

export const saveExportFile = (blob: Blob, fileName: string, format: DataTableExportFormat) => {
  const name = sanitizeFileName(fileName.trim().replace(/\.(xlsx|csv)$/i, ''), 'table')
  downloadBlob(blob, name + '.' + format)
}

import type { DataTableColumn } from './types'
import { getTableExportData, saveExportFile } from './exportUtils'

export const exportTableXlsx = async <T extends object>(
  data: readonly T[],
  columns: readonly DataTableColumn<T>[],
  fileName: string,
  sheetName = 'Data',
) => {
  // Snapshot values before loading the library so paging/editing cannot change this export.
  const { headers, rows } = getTableExportData(data, columns)
  if (!rows.length || !headers.length) return

  const { default: ExcelJS } = await import('exceljs')
  const workbook = new ExcelJS.Workbook()
  const sheet = workbook.addWorksheet(sheetName)
  sheet.columns = headers.map((header) => ({ header, width: 24 }))
  sheet.views = [{ state: 'frozen', ySplit: 1 }]
  sheet.getRow(1).font = { bold: true }
  rows.forEach((values) => {
    const row = sheet.addRow(values)
    values.forEach((value, index) => {
      if (value instanceof Date) row.getCell(index + 1).numFmt = 'yyyy-mm-dd hh:mm:ss'
    })
  })

  const buffer = await workbook.xlsx.writeBuffer()
  const blob = new Blob([new Uint8Array(buffer)], {
    type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
  })
  saveExportFile(blob, fileName, 'xlsx')
}

import { computed, shallowRef, watch } from 'vue'
import type { DataTableColumn, DataTableColumnSetting } from './types'
import { getStoredJson, removeStoredValue, setStoredJson } from '@/utils/storage'

interface ColumnPreference {
  id: DataTableColumnSetting['id']
  visible: boolean
}

const STORAGE_PREFIX = 'zx-admin:table-columns:'

const isConfigurable = <T extends object>(column: DataTableColumn<T>) =>
  column.configurable !== false && (!column.type || column.type === 'default')

const readPreferences = (storageKey?: string): ColumnPreference[] => {
  if (!storageKey) return []
  const saved = getStoredJson(`${STORAGE_PREFIX}${storageKey}`)
  if (typeof saved !== 'object' || saved === null || !('version' in saved)) return []
  if (saved.version !== 2 || !('columns' in saved) || !Array.isArray(saved.columns)) return []
  return saved.columns.filter(
    (item): item is ColumnPreference =>
      typeof item === 'object' &&
      item !== null &&
      (typeof item.id === 'string' ||
        (typeof item.id === 'number' && Number.isInteger(item.id) && item.id >= 0)) &&
      typeof item.visible === 'boolean',
  )
}

const reconcilePreferences = <T extends object>(
  columns: readonly DataTableColumn<T>[],
  saved: ColumnPreference[],
): ColumnPreference[] => {
  const available = new Map(
    columns.flatMap((column, index) =>
      isConfigurable(column) ? [[column.prop || index, column] as const] : [],
    ),
  )
  const preferences: ColumnPreference[] = []

  saved.forEach((item) => {
    if (!available.has(item.id)) return
    preferences.push({ id: item.id, visible: item.visible })
    available.delete(item.id)
  })
  available.forEach((column, id) => {
    preferences.push({ id, visible: !column.defaultHidden })
  })

  const first = preferences[0]
  if (first && !preferences.some((item) => item.visible)) first.visible = true
  return preferences
}

export const useTableColumns = <T extends object>(
  getColumns: () => readonly DataTableColumn<T>[],
  getStorageKey: () => string | undefined,
) => {
  const preferences = shallowRef<ColumnPreference[]>([])

  watch(
    [
      () =>
        getColumns().map(({ prop, type, configurable, defaultHidden }, index) => ({
          id: prop || index,
          type,
          configurable,
          defaultHidden,
        })),
      getStorageKey,
    ],
    ([, storageKey], [, previousKey]) => {
      const saved = storageKey === previousKey ? preferences.value : readPreferences(storageKey)
      preferences.value = reconcilePreferences(getColumns(), saved)
    },
    { immediate: true },
  )

  const settings = computed<DataTableColumnSetting[]>(() => {
    const columns = new Map(getColumns().map((column, index) => [column.prop || index, column]))
    return preferences.value.map((item) => ({
      ...item,
      label: columns.get(item.id)?.label || String(item.id),
    }))
  })

  const visibleColumns = computed(() => {
    const columns = getColumns()
    const byId = new Map(columns.map((column, index) => [column.prop || index, column]))
    let position = 0
    // Only configurable slots are reordered; selection/actions retain their configured positions.
    return columns.flatMap((column) => {
      if (!isConfigurable(column)) return [column]
      const preference = preferences.value[position++]
      const replacement = preference && byId.get(preference.id)
      return preference?.visible && replacement ? [replacement] : []
    })
  })

  const savePreferences = () => {
    const storageKey = getStorageKey()
    if (!storageKey) return
    setStoredJson(`${STORAGE_PREFIX}${storageKey}`, { version: 2, columns: preferences.value })
  }

  const setVisible = (id: DataTableColumnSetting['id'], visible: boolean) => {
    const item = preferences.value.find((column) => column.id === id)
    if (!item || item.visible === visible) return
    if (!visible && preferences.value.filter((column) => column.visible).length <= 1) return
    preferences.value = preferences.value.map((column) =>
      column.id === id ? { ...column, visible } : column,
    )
    savePreferences()
  }

  const moveColumn = (id: DataTableColumnSetting['id'], targetIndex: number) => {
    const columns = [...preferences.value]
    const fromIndex = columns.findIndex((column) => column.id === id)
    if (fromIndex < 0 || targetIndex < 0 || targetIndex >= columns.length) return
    if (fromIndex === targetIndex) return
    const [column] = columns.splice(fromIndex, 1)
    if (!column) return
    columns.splice(targetIndex, 0, column)
    preferences.value = columns
    savePreferences()
  }

  const resetColumns = () => {
    preferences.value = reconcilePreferences(getColumns(), [])
    const storageKey = getStorageKey()
    if (!storageKey) return
    removeStoredValue(`${STORAGE_PREFIX}${storageKey}`)
  }

  return { visibleColumns, settings, setVisible, moveColumn, resetColumns }
}

