import type {
  StocktakeExtreme,
  StocktakeFilters,
  StocktakeMaterialSummary,
  StocktakeRow,
  StocktakeSummary,
} from '@/api/inventory/stocktake'

const quantityKeys = ['wmsQty', 'reelInfoQty'] as const
type QuantityKey = (typeof quantityKeys)[number]

const addQuantities = (totals: StocktakeMaterialSummary, row: StocktakeRow) => {
  quantityKeys.forEach((key) => {
    const value = row[key]
    if (typeof value === 'number' && Number.isFinite(value)) {
      // 全空保持 null；只有读到实际数值后才累加，真实零不会变成空值。
      totals[key] = (totals[key] ?? 0) + value
    }
  })
}

const nullableText = (value: string | null | undefined) =>
  value == null || value === '' ? null : value

// 不依赖当前界面语言的顺序，保证同值料号排序稳定，空值放末尾。
const compareText = (left: string | null, right: string | null) => {
  if (left === right) return 0
  if (left === null) return 1
  if (right === null) return -1
  return left < right ? -1 : 1
}

export const filterStocktakeRows = (
  rows: readonly StocktakeRow[],
  filters: StocktakeFilters,
): StocktakeRow[] => {
  const factory = filters.factory || undefined
  const storageLocation = filters.storageLocation || undefined
  const materials = (filters.materials ?? '')
    .split(/[\s,，;；]+/u)
    .filter(Boolean)
    .map((value) => value.toLowerCase())

  return rows.filter((row) => {
    if (factory !== undefined && row.factory !== factory) return false
    if (storageLocation !== undefined && row.storageLocation !== storageLocation) return false
    if (materials.length === 0) return true
    const material = row.material?.toLowerCase()
    return material !== undefined && materials.some((value) => material.includes(value))
  })
}

export const getStocktakeOptions = (
  rows: readonly StocktakeRow[],
  key: 'factory' | 'storageLocation',
): string[] =>
  [
    ...new Set(
      rows.flatMap((row) => {
        const value = nullableText(row[key])
        return value === null ? [] : [value]
      }),
    ),
  ].sort(compareText)

const getExtreme = (
  materials: readonly StocktakeMaterialSummary[],
  key: QuantityKey,
  direction: 'max' | 'min',
): StocktakeExtreme | null => {
  let extreme: StocktakeExtreme | null = null

  materials.forEach((item) => {
    const value = item[key]
    if (value === null || !Number.isFinite(value)) return
    if (extreme === null || (direction === 'max' ? value > extreme.value : value < extreme.value)) {
      extreme = { material: item.material, value, tieCount: 1 }
    } else if (value === extreme.value) {
      extreme.tieCount += 1
      if (compareText(item.material, extreme.material) < 0) extreme.material = item.material
    }
  })

  return extreme
}

const getTopMaterials = (
  materials: readonly StocktakeMaterialSummary[],
  key: QuantityKey,
): StocktakeMaterialSummary[] =>
  materials
    .filter((item) => item[key] !== null && Number.isFinite(item[key]))
    .sort(
      (left, right) =>
        (right[key] as number) - (left[key] as number) ||
        compareText(left.material, right.material),
    )
    .slice(0, 5)

/** 同料号先合计，再分别计算库存、在制的极值与 Top5；均使用已筛选明细。 */
export const buildStocktakeSummary = (rows: readonly StocktakeRow[]): StocktakeSummary => {
  const factories = new Set<string>()
  const locations = new Set<string>()
  const materials = new Map<string, StocktakeMaterialSummary>()

  rows.forEach((row) => {
    const factory = nullableText(row.factory)
    if (factory !== null) factories.add(factory)

    const storageLocation = nullableText(row.storageLocation)
    if (storageLocation !== null) {
      // 元组编码避免工厂／库位中的分隔符造成分组键碰撞。
      locations.add(JSON.stringify([factory, storageLocation]))
    }

    const material = nullableText(row.material)
    // 没有料号的源记录仍留在明细，不归入虚构料号，也不参与料号极值和榜单。
    if (material === null) return
    let materialGroup = materials.get(material)
    if (!materialGroup) {
      materialGroup = { material, wmsQty: null, reelInfoQty: null }
      materials.set(material, materialGroup)
    }
    addQuantities(materialGroup, row)
  })

  const materialGroups = [...materials.values()]
  return {
    total: rows.length,
    factoryCount: factories.size,
    materialCount: materials.size,
    storageLocationCount: locations.size,
    inventoryMax: getExtreme(materialGroups, 'wmsQty', 'max'),
    inventoryMin: getExtreme(materialGroups, 'wmsQty', 'min'),
    wipMax: getExtreme(materialGroups, 'reelInfoQty', 'max'),
    wipMin: getExtreme(materialGroups, 'reelInfoQty', 'min'),
    inventoryTop: getTopMaterials(materialGroups, 'wmsQty'),
    wipTop: getTopMaterials(materialGroups, 'reelInfoQty'),
  }
}

